  reg [31:0] regs [0:31];

  // Read and write port signals
  reg [4:0] rd_addr_a;
  reg [4:0] rd_addr_b;
  reg [4:0] wr_addr;
  reg wr_en;

  // Output data register
  reg [7:0] out_data_reg;

  // Sequential logic for register file
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      // Reset all registers to zero
      for (int i = 0; i < 32; i = i + 1) begin
        regs[i] <= 32'd0;
      end
      // Reset control signals
      rd_addr_a <= 5'd0;
      rd_addr_b <= 5'd0;
      wr_addr <= 5'd0;
      wr_en <= 1'b0;
      out_data_reg <= 8'd0;
    end else begin
      // Write operation
