      rd_addr_a <= rd_addr_a;  // Placeholder, actual read address would come from external control
      rd_addr_b <= rd_addr_b;  // Placeholder, actual read address would come from external control
    end
  end

  // Output data is the lower 8 bits of register 0 (for this specific implementation)
  assign out_data = regs[0][7:0];

endmodule

